// ---- PASS B station steps (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py) ----

void networkSlantIonoBlockColumns(StationCarryFrame& carry) {
    // ---- From the station build (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    StationBuild& build = carry.build;
    const NetworkRunContext& ctx = build.ctx;
    double pl_now_s = build.clock.pl_now_s;
    const int i = build.i;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    const bool legacy_local_inject = carry.legacy_local_inject;
    const bool do_amb_carry = carry.do_amb_carry;
    const Eigen::VectorXd& x_lin = carry.x_lin;
    // The alias lines of networkPassB_ this function reads, verbatim (card NOM3 step PB1b).
    const double pl_max_gap_s  = ctx.knobs.pl_max_gap_s;
    // Live predicate for I-in-block (network.carry_iono_in_block): the station's
    // carried per-LOS slant-iono columns join the F3 whitened block.  Conjoined with
    // pl_blk_on as for the ZWD, and here the conjunction is load-bearing: the card has
    // no diagonal fallback row (a diagonal per-LOS iono prior is the FALSIFIED
    // QUEUE-8(b) vehicle), so off the block path there is nothing to do.  The loader
    // already refuses the arm without phase_leveling + phase_leveling_local_block;
    // this is the live half of that gate.
    const bool   iono_blk_on   = ctx.knobs.iono_blk_on;
    const double iono_blk_q    = ctx.knobs.iono_blk_q_m2;      // m² at L1, per epoch
    const double iono_blk_gap_s = ctx.knobs.iono_blk_max_gap_s;
    auto& iono_blk_carry = ctx.carry.iono_blk_carry;  // I-in-block: produce phase reads only
    // ---- End of the bindings ----

    if (!(legacy_local_inject && do_amb_carry)) return;
    // --- I-in-block (network.carry_iono_in_block): collect this station's
    //     carried per-LOS slant-iono columns for the same block the
    //     ambiguities are about to build.  Walked here, before the block
    //     build, because the harvest reads R.pl_iono to decide which columns
    //     joined `cols`, and R.pl_iono is recorded for every present LOS,
    //     folded or not, so the carry keeps tracking the solution through the
    //     epochs it cannot act on (the pl_zwd_present pattern).
    //
    //     Why the per-LOS iono belongs in the block and not on a diagonal row:
    //     the station's B carried band priors already assert this LOS's iono
    //     direction implicitly (one per band), so an independent diagonal iono
    //     prior asserts it once more (the B-fold over-count of
    //     SPEC_amb_iono_split_overcount §7 item 17, and the structural reason
    //     network.carry_iono was falsified four times in QUEUE 8(b)).  Inside
    //     the block the harvested (N_rr⁻¹) cross terms subtract that overlap
    //     exactly.  Consequently there is no inject-side var floor (the floor
    //     bounded how far a double-counted prior could out-stiffen the code
    //     channel; exactness replaces it); a first sighting already carries
    //     nothing.
    std::vector<LocalBlockCol>& iono_bc = carry.iono_bc;
    if (iono_blk_on) {
        // q is per epoch (m² at L1), so the gap needs an epoch length, taken
        // from the run itself (the current PASS-B time minus the previous
        // harvest stamp is this epoch's spacing), so the knob means the same
        // thing at 1 s and 30 s cadence and no nominal-rate config is needed.
        // Floored at one epoch: a same-epoch re-fold still pays one q.
        double dt_ep = pl_now_s - ctx.carry.pl_prev_now_s;
        if (!std::isfinite(dt_ep) || dt_ep <= 0.0 || dt_ep > pl_max_gap_s)
            dt_ep = 0.0;   // first epoch / implausible spacing ⇒ gap_ep = 1
        for (const auto& [isat, iidx_sz] : st.sm->getIonosphereStates()) {
            const int iidx = static_cast<int>(iidx_sz);
            if (iidx < 0 || iidx >= x_lin.size()) continue;
            if (!std::isfinite(x_lin(iidx))) continue;
            const auto ihit = h2local.find(iidx);
            if (ihit == h2local.end()) continue;  // iono column not in A_r this epoch
            const Eigen::Index icol = static_cast<Eigen::Index>(ihit->second);
            R.pl_iono.emplace_back(isat, icol, x_lin(iidx));
            const auto iit = iono_blk_carry.find({static_cast<int>(i), isat});
            if (iit == iono_blk_carry.end()) continue;  // first sighting / post-erase: cold by design
            const double igap = pl_now_s - iit->second.last_seen_s;
            if (carryPastHorizon(pl_now_s, iit->second.last_seen_s, iono_blk_gap_s)) {
                // Invariant #1's absent-satellite edge: a stale LOS is refused,
                // never aged into a fold.  The harvest prune erases it.
                ++R.pl_blk_iono_gap_drop;
                ++R.prm_iono_gap_skip;   // card PRM phase 3a
                continue;
            }
            const double gap_ep =
                (dt_ep > 0.0) ? std::max(1.0, igap / dt_ep) : 1.0;
            const double ivar_eff = iit->second.var + iono_blk_q * gap_ep;
            if (!(ivar_eff > 0.0) || !std::isfinite(ivar_eff)) continue;
            iono_bc.push_back(LocalBlockCol{
                icol, x_lin(iidx), &iit->second, ivar_eff,
                std::max(0.0, igap), /*vce_fac=*/1.0,
                /*is_zwd=*/false, /*is_iono=*/true});
            if (const auto col_sat = SatId::parse(isat))   // its block row's tag (card NOM N2a)
                iono_bc.back().sat = *col_sat;
        }
    }
}

// ---- End of the PASS B station steps (card NOM3 step PB1b) ----

// ---- Harvest half (card NOM3 step HV1; generated by scripts/nom_hv1_cut.py) ----

void networkHarvestSlantIonoBlock(NetworkRun& run, const NetworkEpoch& ep, HarvestBorder& border,
                                  const std::vector<StationHarvestBlock>& blocks) {
    // ---- From the run, the epoch and the harvest (card NOM3 step HV1; generated by
    //      scripts/nom_hv1_cut.py, each line checked by scripts/nom_hv1_verify.py). ----
    NetworkRunContext& ctx = run.ctx;
    const NetworkEstimator& est = run.engines.est;
    const Eigen::VectorXd& x_s = ep.solve.x_s;
    std::vector<NetStation>& stations = run.setup.stations;
    const std::vector<int>& est_index_of = ep.assembly.est_index_of;
    const std::vector<StationAssembly>& asm_res = ep.assembly.asm_res;
    const NetworkSbasis::Plan& plan = ep.solve.plan;
    double pl_now_s = ep.clock.pl_now_s;
    const bool   carry_cpl_cond = ctx.knobs.carry_cpl_cond;
    // Iono in the local block (network.carry_iono_in_block): the per-LOS iono columns
    // join the same harvest block, on the same live predicate, for the same reason.
    // Off ⇒ `cols` is untouched and PlHarvestBlock::C keeps its dimension
    // (byte-identical).
    const bool   iono_blk_on = ctx.knobs.iono_blk_on;
    SharedHistoryHarvest& shx_h = border.shx_h;
    // ---- End of the bindings ----
    // --- In-block slant-iono carry (network.carry_iono_in_block): harvest each
    //     station's per-LOS iono posteriors through the same per-column solve the
    //     ambiguities used, write their rows of the station's harvest block, stash
    //     the absolute value, and prune the stale entries.
    //
    //     Independent loop (as for the ZWD), so it runs for stations whose
    //     ambiguity harvest produced nothing.  It differed from the harvest of the
    //     retired diagonal slant-iono carry (queue 8(b)) in three deliberate ways:
    //       * the cross terms are gathered (they subtract the B-fold over-count at
    //         inject); queue 8(b) took the diagonal alone;
    //       * the coupling row is harvested: an in-block column is folded like an
    //         ambiguity, border regression included, which makes the prior exact
    //         given the border (the rx-CB "no shared footprint" rationale applied to
    //         the diagonal vehicle, not to this one);
    //       * the value is absolute (x_lin + x_r).  network_ionosphere.csv writes
    //         x_r alone and is not frame-complete; a carry that is not
    //         frame-complete would re-inject a correction against a moved
    //         linearization point.
    //     A LOS whose harvest fails keeps blk = nullptr, so every pair with it is
    //     zeroed and counted (n_pl_blk_iono_missing_cross), which is the safe
    //     degrade.
    if (!iono_blk_on) return;
    auto& iono_blk_carry = ctx.carry.iono_blk_carry;
    for (size_t i = 0; i < stations.size(); ++i) {
        if (est_index_of[i] < 0) continue;
        const StationAssembly& R = asm_res[i];
        if (R.pl_iono.empty()) continue;
        const std::size_t est_idx = static_cast<std::size_t>(est_index_of[i]);
        const std::shared_ptr<PlHarvestBlock> iblk = blocks[i].segmentBlock(BlockSegment::Iono);
        const std::vector<Eigen::Index>* icross_cols =
            iblk ? &blocks[i].cols : nullptr;
        const Eigen::Index irow0 = iblk ? blocks[i].rowOf(BlockSegment::Iono) : Eigen::Index{-1};
        std::vector<Eigen::Index> icols;
        icols.reserve(R.pl_iono.size());
        for (const auto& t : R.pl_iono) icols.push_back(std::get<1>(t));
        Eigen::VectorXd xr, vard;
        try {
            xr = est.reconstructStation(est_idx, x_s);
            if (!carry_cpl_cond)   // the coupling carry (card 1) uses the pure conditional (N_rr⁻¹)_cc
                vard = est.conditionalLocalVarianceDiag(est_idx, icols,
                                                        plan.shared_datum);
        } catch (...) { continue; }
        for (std::size_t a = 0; a < R.pl_iono.size(); ++a) {
            const auto& [isat, icol, ix_lin] = R.pl_iono[a];
            if (icol < 0 || icol >= xr.size()) continue;
            const double value_abs = ix_lin + xr(icol);
            if (!std::isfinite(value_abs)) continue;
            double var;
            std::vector<CoupledShared> coupling;
            Eigen::VectorXd icross;
            if (carry_cpl_cond) {
                auto hc = networkHarvestColumn(run, ep, border, est_idx, icol, icross_cols,
                                                                iblk ? &icross : nullptr);
                var = hc.first; coupling = std::move(hc.second);
            } else {
                var = (a < static_cast<std::size_t>(vard.size())) ? vard(a) : -1.0;
            }
            if (!(var > 0.0) || !std::isfinite(var)) continue;
            const auto key = std::make_pair(static_cast<int>(i), isat);
            LocalCarry ent{value_abs, var, pl_now_s, std::move(coupling)};
            // birth_ep / birth_s / var_first survive a re-stash and restart only
            // on an erase-and-rebirth (a T4 erase, or a gap prune): the ambiguity
            // carry's rule, applied through the ambiguity carry's own helper, so
            // the age of an iono carry means the same thing.  (This map is not
            // snapshotted, so it never sees a restored sentinel; the shared helper
            // keeps the rule correct if it ever is.)
            const auto oit = iono_blk_carry.find(key);
            const LocalCarry* iprev =
                (oit != iono_blk_carry.end()) ? &oit->second : nullptr;
            ent.var_first = iprev ? iprev->var_first : var;
            localCarryStampBirth(
                ent, iprev,
                static_cast<long long>(ctx.counters.n_loop_epochs), pl_now_s);
            // Row irow0 + a of the station's harvest block is this iono column's
            // n_c read at every carried column of the station (its own entry
            // equals `var`, the pure conditional).  The entry then points at the
            // same PlHarvestBlock as the ambiguity and ZWD entries, so next
            // epoch's inject pairs iono↔ambiguity, iono↔ZWD and iono↔iono by
            // pointer equality, as it pairs ambiguity↔ambiguity.
            if (iblk && irow0 >= 0 && icross.size() == iblk->C.rows()) {
                const Eigen::Index irow = irow0 + static_cast<Eigen::Index>(a);
                if (irow < iblk->C.rows()) {
                    iblk->C.row(irow) = icross.transpose();
                    ent.blk     = iblk;
                    ent.blk_idx = static_cast<int>(irow);
                }
            }
            iono_blk_carry[key] = std::move(ent);
            networkSharedHistoryNoteEntry(shx_h, est_idx, icol, SharedHistoryMap::Iono,
                                          static_cast<int>(i), isat);   // card SCL2 X2; no-op off
        }
    }
    // Decoupling edge (invariants #1 and #7): a LOS unseen past the horizon is
    // dropped, not aged into a fold.  It is counted, because this is the
    // eclipse / set edge, and a run whose count is 0 over a full day did not
    // exercise it.  The horizon is the registry's: under the block carry it is
    // network.carry_iono_in_block_max_gap_s, the same double
    // (ctx.knobs.iono_blk_max_gap_s) this prune read before card PRM phase 3b.
    carryGapPrune(iono_blk_carry, pl_now_s,
                  ctx.params.spec(NetworkParamKind::SlantIono).gap_horizon_s,
                  [&](const auto&) {
                      ++ctx.counters.n_iono_blk_gap_drop;
                      prmRespond(ctx.counters.prm_resp, ResponseSite::IonoGapPrune);   // card PRM phase 3a
                  });
}

